import React from 'react';

const OL = '#2a2340';
const S = { stroke: OL, strokeWidth: 2.2, strokeLinejoin: 'round', strokeLinecap: 'round' };
const P = (d, fill, k, x = {}) => <path key={k} d={d} fill={fill} {...S} {...x} />;
const C = (cx, cy, r, fill, k, x = {}) => <circle key={k} cx={cx} cy={cy} r={r} fill={fill} {...S} {...x} />;
const star = (x, y, r, fill = '#ffd23f', k) => { const p = Array.from({ length: 10 }, (_, i) => { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * 0.45 : r; return `${(x + rr * Math.cos(a)).toFixed(1)},${(y + rr * Math.sin(a)).toFixed(1)}`; }).join(' '); return <polygon key={k} points={p} fill={fill} {...S} strokeWidth="1.4" />; };

